-- Catálogo Blue Haven. Ejecutar después de la migración de estructura.
insert into public.peces(nombre,rareza,velocidad,peso_seleccion,sprite,datos)
select p->>'nombre',(p->>'rareza')::int,(p->>'velocidad')::real,(p->>'pesoSeleccion')::real,p->>'sprite',p
from jsonb_array_elements($catalogo$[{"nombre":"Carpa","nombreCientifico":"Cyprinus carpio","rareza":1,"sprite":"Carpa.svg","habitat":"Aguas tranquilas de lagos y ríos lentos","alimentacion":"Omnívoro: plantas, insectos, gusanos","tamaño":"30-50 cm","peso":"1-3 kg","dificultad":"Fácil","descripcion":"La carpa es un pez resistente y común en aguas dulces. Es ideal para principiantes.","ceboRecomendado":"Lombriz o masa","datoCurioso":"Puede vivir hasta 20 años en condiciones ideales.","velocidad":1,"pesoSeleccion":15},{"nombre":"Bagre","nombreCientifico":"Rhamdia quelen","rareza":1,"sprite":"Bagre.png","habitat":"Fondos lodosos y pozones tranquilos del río y lago","alimentacion":"Omnívoro bentónico: peces chicos, larvas y crustáceos","tamaño":"25-45 cm","peso":"0.8-2.5 kg","dificultad":"Fácil","descripcion":"Pez de fondo reconocible por sus largos barbillones en forma de bigotes con los que detecta alimento en aguas turbias.","ceboRecomendado":"Lombriz o trozo de pescado","datoCurioso":"Sus bigotes son receptores sensoriales con miles de papilas gustativas para saborear antes de morder.","velocidad":1.1,"pesoSeleccion":18},{"nombre":"Trucha Arcoíris","nombreCientifico":"Oncorhynchus mykiss","rareza":2,"sprite":"Trucha.svg","habitat":"Ríos y arroyos de aguas frías y oxigenadas","alimentacion":"Carnívoro: insectos, pequeños peces, crustáceos","tamaño":"25-40 cm","peso":"0.5-2 kg","dificultad":"Media","descripcion":"Conocida por su coloración iridiscente. Es un pez deportivo muy valorado.","ceboRecomendado":"Mosca o cucharilla","datoCurioso":"Su nombre proviene de la franja rosada que recorre su costado.","velocidad":1.8,"pesoSeleccion":16},{"nombre":"Cangrejo","nombreCientifico":"Aegla uruguayana","rareza":2,"sprite":"Cangrejo.png","habitat":"Riberas rocosas y grietas con vegetación del lago","alimentacion":"Carroñero y omnívoro: algas, moluscos y restos orgánicos","tamaño":"10-20 cm","peso":"0.2-0.6 kg","dificultad":"Media","descripcion":"Crustáceo de caparazón acorazado y firmes pinzas. Camina lateralmente y se defiende levantando sus tenazas.","ceboRecomendado":"Carne o trozo de molusco","datoCurioso":"Si pierde una extremidad o pinza en combate, es capaz de regenerarla por completo en su siguiente muda.","velocidad":1.7,"pesoSeleccion":16},{"nombre":"Atún","nombreCientifico":"Thunnus thynnus","rareza":2,"sprite":"Atun.png","habitat":"Aguas abiertas del océano","alimentacion":"Carnívoro: peces pequeños, calamares, crustáceos","tamaño":"50-100 cm","peso":"5-20 kg","dificultad":"Media","descripcion":"Un nadador veloz y poderoso. Requiere equipo resistente.","ceboRecomendado":"Señuelo artificial","datoCurioso":"Puede nadar a 70 km/h y sumergirse a 1000 metros.","velocidad":2.3,"pesoSeleccion":15},{"nombre":"Pez Globo","nombreCientifico":"Tetraodontidae","rareza":2,"sprite":"Pez_Globo.png","habitat":"Aguas costeras tropicales y arrecifes poco profundos","alimentacion":"Invertebrados: caracoles, cangrejos y erizos","tamaño":"15-35 cm","peso":"0.4-1.5 kg","dificultad":"Media","descripcion":"Se infla ingiriendo agua para triplicar su tamaño ante cualquier peligro y disuadir atacantes.","ceboRecomendado":"Camarón o trozo de molusco","datoCurioso":"Posee tetrodotoxina, un veneno letal más potente que el cianuro, pero en Japón es un manjar.","velocidad":2,"pesoSeleccion":14},{"nombre":"Tortuga","nombreCientifico":"Trachemys dorbigni","rareza":2,"sprite":"Tortuga.png","habitat":"Lagunas, remansos soleados y bancos de vegetación acuática","alimentacion":"Omnívoro: plantas acuáticas, caracoles, renacuajos","tamaño":"20-40 cm","peso":"1.5-5 kg","dificultad":"Media","descripcion":"Reptil de caparazón hidrodinámico y nado tranquilo. Suele descansar sobre troncos o piedras flotantes al sol.","ceboRecomendado":"Vegetal acuático o masa","datoCurioso":"Puede pasar largos períodos sumergida ralentizando su ritmo cardíaco hasta apenas unas pocas pulsaciones por minuto.","velocidad":2,"pesoSeleccion":14},{"nombre":"Calamar","nombreCientifico":"Loligo vulgaris","rareza":3,"sprite":"Calamar.png","habitat":"Aguas costeras y mar abierto","alimentacion":"Carnívoro: peces pequeños, crustáceos","tamaño":"20-40 cm","peso":"0.5-2 kg","dificultad":"Difícil","descripcion":"Molusco cefalópodo de cuerpo alargado. Es escurridizo y rápido.","ceboRecomendado":"Señuelo luminoso","datoCurioso":"Tiene tres corazones y sangre azul.","velocidad":3.1,"pesoSeleccion":11},{"nombre":"Pulpo","nombreCientifico":"Octopus vulgaris","rareza":3,"sprite":"Pulpo.png","habitat":"Cuevas rocosas submarinas y grietas profundas","alimentacion":"Carnívoro: cangrejos, langostas, bivalvos y peces","tamaño":"40-90 cm","peso":"2-7 kg","dificultad":"Difícil","descripcion":"Cefalópodo fascinante de ocho brazos provistos de ventosas. Es un maestro del camuflaje que cambia de color y textura al instante.","ceboRecomendado":"Cangrejo vivo o señuelo brillante","datoCurioso":"Posee tres corazones, sangre azul basada en cobre y dos tercios de sus neuronas están en sus tentáculos.","velocidad":3,"pesoSeleccion":11},{"nombre":"Dragón del Lago","nombreCientifico":"Draco lacustris","rareza":3,"sprite":"Dragon.svg","habitat":"Aguas profundas y oscuras","alimentacion":"Desconocida","tamaño":"???","peso":"???","dificultad":"Difícil","descripcion":"Una criatura mítica que pocos pescadores han logrado ver.","ceboRecomendado":"???","datoCurioso":"Se dice que solo aparece en noches de luna llena.","velocidad":3,"pesoSeleccion":9},{"nombre":"Esturión Gigante","nombreCientifico":"Huso huso","rareza":4,"sprite":"Esturion.svg","habitat":"Aguas profundas de grandes ríos y lagos","alimentacion":"Carnívoro: peces, moluscos, crustáceos","tamaño":"100-200 cm","peso":"20-100 kg","dificultad":"Muy difícil","descripcion":"Un pez prehistórico de gran tamaño. Su captura es un desafío legendario.","ceboRecomendado":"Pez vivo o trozo de pescado","datoCurioso":"Existe desde la era de los dinosaurios, hace 200 millones de años.","velocidad":3.6,"pesoSeleccion":6},{"nombre":"Ballena Azul","nombreCientifico":"Balaenoptera musculus","rareza":4,"sprite":"Ballena_azul.png","habitat":"Océanos de todo el mundo","alimentacion":"Carnívoro: krill y pequeños peces","tamaño":"2000-3000 cm","peso":"100000-150000 kg","dificultad":"Extrema","descripcion":"El animal más grande que jamás ha existido en la Tierra.","ceboRecomendado":"???","datoCurioso":"Su corazón es del tamaño de un auto pequeño.","velocidad":4,"pesoSeleccion":5},{"nombre":"Pez Remo","nombreCientifico":"Regalecus glesne","rareza":5,"sprite":"Pez_remo.svg","habitat":"Aguas profundas del océano (200-1000m)","alimentacion":"Carnívoro: krill, pequeños peces, calamares","tamaño":"300-800 cm","peso":"20-50 kg","dificultad":"Extrema","descripcion":"El pez óseo más largo del mundo. Vive en las profundidades abisales.","ceboRecomendado":"???","datoCurioso":"Es considerado el origen de las leyendas de serpientes marinas.","velocidad":4.2,"pesoSeleccion":3},{"nombre":"Orca","nombreCientifico":"Orcinus orca","rareza":5,"sprite":"Orca.png","habitat":"Aguas profundas, frías y mar abierto","alimentacion":"Depredador alfa: peces grandes, calamares y mamíferos marinos","tamaño":"600-800 cm","peso":"3500-6000 kg","dificultad":"Extrema","descripcion":"El depredador ápice del océano. Dotada de enorme fuerza, nado veloz e inteligencia táctica legendaria.","ceboRecomendado":"Señuelo de aguas profundas o pez grande","datoCurioso":"Son animales muy sociales y cada manada posee dialectos y técnicas de caza exclusivas enseñadas de madres a crías.","velocidad":4.3,"pesoSeleccion":3}]$catalogo$::jsonb) p
on conflict(nombre) do update set rareza=excluded.rareza,velocidad=excluded.velocidad,peso_seleccion=excluded.peso_seleccion,sprite=excluded.sprite,datos=excluded.datos;
